void roundtrip(const std::filesystem::path& directory){std::filesystem::create_directories(directory);for(bool trim:{false,true}){auto d=fixture();d.resizeCanvas(2,3,CanvasAnchor::NorthWest,1,0,trim);const auto path=directory/(trim?"trim.moonsprite":"retain.moonsprite");project::saveDocumentAtomic(d,path);CHECK(!d.dirty());std::ifstream in(path,std::ios::binary);auto bytes=std::make_shared<const project::Bytes>(std::istreambuf_iterator<char>(in),std::istreambuf_iterator<char>());auto imported=project::prepareEditableImport(project::readProjectManifest(bytes));timeline::Timeline reopened(imported.timeline);CHECK(imported.width==2&&imported.height==3&&reopened.state().frames[1].disabled&&reopened.state().loopSections[0].direction=="reverse");for(const auto& c:d.timeline().state().cels){const auto before=d.timeline().resolveSurface(c.id),after=reopened.resolveSurface(c.id);CHECK(after.surface&&after.surface->width==before.surface->width&&after.surface->height==before.surface->height&&after.surface->offsetX==before.surface->offsetX&&after.surface->offsetY==before.surface->offsetY&&after.surface->pixels==before.surface->pixels&&after.surface->storageOriginX.value_or(0)==0);const auto* saved=reopened.findCelById(c.id);CHECK(saved->opacity==c.opacity&&saved->zIndex==c.zIndex);}CHECK(reopened.findCelById("a1")->linkedCelId==std::optional<std::string>{"a0"});}}
